; copy4.asm -- chapter 8: one job, four ways
; generated by gen08.py
        INCLUDE "msx.inc"
        OUTPUT "copy4.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
BUF1    EQU RAM_START + $40 + 0
BUF2    EQU RAM_START + $40 + 8
BUF3    EQU RAM_START + $40 + 16
BUF4    EQU RAM_START + $40 + 24
IM2_TABLE EQU $C100             ; 257 bytes of $C2: the interrupt vector is $C2C2
IM2_JUMP  EQU $C2C2
; The same eight bytes copied into the RAM four ways. Each way starts by
; changing the border colour and runs four times, so the bottom border draws
; how long each takes: figure 8.2.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        ld hl, IM2_TABLE        ; an interrupt of our own (chapter 17)
        ld (hl), $C2
        ld de, IM2_TABLE + 1
        ld bc, 256
        ldir
        ld a, $C3               ; JP handler, at $C2C2
        ld (IM2_JUMP), a
        ld hl, handler
        ld (IM2_JUMP + 1), hl
        ld a, high IM2_TABLE
        ld i, a
        im 2
        VDP_REG 1, $E0          ; display on, frame interrupt on
        ei
main:   halt                    ; the frame interrupt: the beam leaves the paper
        ld b, 13                ; a pause: every change of colour falls
pause:  djnz pause              ; in the columns the VDP draws (gen08.py)
col1:   VDP_REG 7, BLACK       ; way 1, LD A,(nn), starts
        ld b, 4                ; 4 times, for a band long enough to see
way1:
        ld a, (glyph+0)
        ld (BUF1+0), a
        ld a, (glyph+1)
        ld (BUF1+1), a
        ld a, (glyph+2)
        ld (BUF1+2), a
        ld a, (glyph+3)
        ld (BUF1+3), a
        ld a, (glyph+4)
        ld (BUF1+4), a
        ld a, (glyph+5)
        ld (BUF1+5), a
        ld a, (glyph+6)
        ld (BUF1+6), a
        ld a, (glyph+7)
        ld (BUF1+7), a
        djnz way1               ; B - 1, and again until B is 0 (chapter 11)
col2:   VDP_REG 7, DARK_BLUE   ; way 2, LD A,(DE), starts
        ld b, 4                ; 4 times, for a band long enough to see
way2:
        ld de, glyph
        ld hl, BUF2
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        ld a, (de)
        ld (hl), a
        inc de
        inc hl
        djnz way2               ; B - 1, and again until B is 0 (chapter 11)
col3:   VDP_REG 7, LIGHT_GREEN ; way 3, LD A,(IX+d), starts
        ld b, 4                ; 4 times, for a band long enough to see
way3:
        ld ix, glyph
        ld hl, BUF3
        ld a, (ix+0)
        ld (hl), a
        inc hl
        ld a, (ix+1)
        ld (hl), a
        inc hl
        ld a, (ix+2)
        ld (hl), a
        inc hl
        ld a, (ix+3)
        ld (hl), a
        inc hl
        ld a, (ix+4)
        ld (hl), a
        inc hl
        ld a, (ix+5)
        ld (hl), a
        inc hl
        ld a, (ix+6)
        ld (hl), a
        inc hl
        ld a, (ix+7)
        ld (hl), a
        inc hl
        djnz way3               ; B - 1, and again until B is 0 (chapter 11)
col4:   VDP_REG 7, BLACK       ; way 4, LD (HL),n, starts
        ld b, 4                ; 4 times, for a band long enough to see
way4:
        ld hl, BUF4
        ld (hl), %00011000
        inc hl
        ld (hl), %00111100
        inc hl
        ld (hl), %01100110
        inc hl
        ld (hl), %11011011
        inc hl
        ld (hl), %11011011
        inc hl
        ld (hl), %01100110
        inc hl
        ld (hl), %00111100
        inc hl
        ld (hl), %00011000
        inc hl
        djnz way4               ; B - 1, and again until B is 0 (chapter 11)
col5:   VDP_REG 7, WHITE        ; all four done
        jp main                 ; too far back for JR

handler:
        in a, (VDP_CTRL)        ; reading the status answers the interrupt
        ei
        ret

glyph:  db %00011000, %00111100, %01100110, %11011011, %11011011, %01100110, %00111100, %00011000
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
        ASSERT $ == $8000
